def forward(groups):
    dt = datetime.strptime(groups[0] + ' ' + groups[1], '%y/%m/%d %H:%M:%S')
    return {'stored': [int(dt.timestamp() * 1000)], 'layout': []}

def inverse(record):
    timestamp = int(record['stored'][0]) / 1000
    dt = datetime.fromtimestamp(timestamp)
    return dt.strftime('%y/%m/%d %H:%M:%S')
